'use strict';
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const state = {data:null, models:[], token:'', filter:'all', query:'', compare:'refinery_large', timeMetric:'seconds', sort:'default', device:'cpu', selectedModel:'refinery', job:null, timer:null, history:[], returnFocus:null};
const paths = {
 grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',
 chart:'M4 3v17h17 M8 15v-4 M13 15V6 M18 15V9', terminal:'M4 4h16v16H4z M7 8l3 3-3 3 M13 15h4',
 layers:'M12 3L2 8l10 5 10-5-10-5 M3 12l9 5 9-5 M3 16l9 5 9-5',
 arrow:'M5 12h14 M14 7l5 5-5 5', diagonal:'M6 18L18 6 M6 6h12v12', plus:'M12 5v14 M5 12h14',
 chip:'M6 6h12v12H6z M9 9h6v6H9z M9 3v3 M15 3v3 M9 18v3 M15 18v3 M3 9h3 M3 15h3 M18 9h3 M18 15h3',
 check:'M5 12l4 4L19 6', shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3 M8 11l3 3 5-6',
 clock:'M12 8v5l4 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0', info:'M12 11v6 M12 7v.1 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
 upload:'M12 16V3 M7 8l5-5 5 5 M4 15v5h16v-5', download:'M12 3v13 M7 11l5 5 5-5 M4 16v4h16v-4',
 search:'M21 21l-6-6 M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0', close:'M6 6l12 12 M18 6L6 18',
 menu:'M4 6h16 M4 12h16 M4 18h16', play:'M7 4l14 8-14 8V4', stop:'M6 6h12v12H6z',
 trend:'M3 17l6-6 4 3 8-10 M15 4h6v6', bolt:'M13 2L4 14h7l-1 8 10-13h-7l1-7', file:'M6 3h8l5 5v13H6V3 M14 3v6h5 M9 13h7 M9 17h5', warning:'M12 3L2 21h20L12 3 M12 9v5 M12 17v.1', eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12 M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0'
};
function icon(name){return `<i data-icon="${name}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg></i>`}
function icons(){ $$('i[data-icon]:empty').forEach(i=>i.innerHTML=`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[i.dataset.icon]||paths.grid}"/></svg>`); }
const esc = value => String(value ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num = v => v==null?'—':Number(v).toLocaleString('en-US',{maximumFractionDigits:0});
const sci = v => v==null?'—':v===0?'0':Number(v).toExponential(2);
const time = v => v==null?'—':v>=1?`${v.toFixed(2)} s`:`${(v*1000).toFixed(v*1000<10?2:1)} ms`;
const objective = v => v==null?'—':Number(v).toLocaleString('en-US',{maximumFractionDigits:6});
const engineName = e => ({cpu:'VANTAGE CPU',cuda:'VANTAGE GPU',highs:'HiGHS'})[e]||e;
const route = ()=>location.hash.slice(1).split('?')[0]||'overview';
function badge(status){const good=['OPTIMAL','VERIFIED_OPTIMAL'].includes(status); const labels={OPTIMAL:'Optimal',ITERATION_LIMIT:'Iteration limit',TIME_LIMIT:'Time limit',UNKNOWN:'Unresolved',ERROR:'Error',UNSUPPORTED:'Unsupported',INTERRUPTED:'Interrupted',running:'Running',queued:'Queued'};return `<span class="pill ${good?'green':['running','queued'].includes(status)?'gray':'orange'}">${good?icon('check'):''}${esc(labels[status]||status)}</span>`}
async function api(path,body){const r=await fetch(path,{headers:body?{'Content-Type':'application/json','X-Vantage-Token':state.token}:{},method:body?'POST':'GET',body:body?JSON.stringify(body):undefined}); const d=await r.json(); if(!r.ok)throw Error(d.error||'Request failed');return d;}
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,6000);}
function heading(kicker,title,subtitle,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="actions">${actions}</div></div>`;}
function caseById(id){return state.data.cases.find(c=>c.id===id);}
function metricCards(){const d=state.data;const max=d.max_objective_error;return `<div class="stats-grid">
<div class="stat"><div class="stat-label">Verified optimal cases ${icon('shield')}</div><div class="stat-value">${d.counts.cuda}<span class="muted-number"> / ${d.total}</span></div><div class="stat-caption"><span class="mini-pill">GPU</span> Distinct tested models</div></div>
<div class="stat"><div class="stat-label">GPU acceleration ${icon('bolt')}</div><div class="stat-value">${d.speedup?.toFixed(2)||'—'}<span class="unit">×</span></div><div class="stat-caption"><span class="mini-pill">VS CPU</span> Large synthetic LP</div></div>
<div class="stat"><div class="stat-label">Objective agreement ${icon('eye')}</div><div class="stat-value">${max==null?'—':max.toExponential(1)}</div><div class="stat-caption">Worst relative error vs HiGHS¹</div></div>
<div class="stat"><div class="stat-label">Reference solve coverage ${icon('layers')}</div><div class="stat-value">${d.counts.highs}<span class="muted-number"> / ${d.total}</span></div><div class="stat-caption"><span class="mini-pill clay">HiGHS</span> Same selected cases</div></div></div>`;}
function chart(caseId=state.compare,select=false){const c=caseById(caseId)||state.data.cases[0];if(!c)return `<div class="panel"><p class="empty-table">No benchmark data yet. Run scripts/run_demo.sh.</p></div>`;const values=['cpu','cuda','highs'].map(k=>c.engines[k]?.[state.timeMetric]??0);const max=Math.max(...values,0.001);const ticks=[0,max/3,2*max/3,max];return `<section class="panel" aria-label="Solver timing comparison"><div class="panel-header"><div><span class="overline">PERFORMANCE / ${c.category==='Scalability'?'SYNTHETIC LP':esc(c.category.toUpperCase())}</span><h2>${select?'Same model. Three perspectives.':'Compute backend comparison.'}</h2><p>${state.timeMetric==='seconds'?'Measured execution. Transfer and setup costs included.':state.timeMetric==='iteration_seconds'?'Iteration loop only. Setup, transfer and monitoring excluded.':'Full process wall time, including program startup.'}</p></div><span class="pill">3 RUN MEDIAN</span></div>
${select?`<div class="comparison-controls"><select id="compare-case" class="select" aria-label="Comparison model">${state.data.cases.map(v=>`<option value="${v.id}" ${c.id===v.id?'selected':''}>${esc(v.name)}</option>`).join('')}</select><select id="time-metric" class="select" aria-label="Timing measurement"><option value="seconds" ${state.timeMetric==='seconds'?'selected':''}>End-to-end</option><option value="iteration_seconds" ${state.timeMetric==='iteration_seconds'?'selected':''}>Iteration time</option><option value="wall_seconds" ${state.timeMetric==='wall_seconds'?'selected':''}>Process wall time</option></select></div>`:''}
<div class="comparison-wrap"><div class="chart-meta"><b>${esc(c.name)}</b><span>${num(c.columns)} VARIABLES <span class="footer-dot">·</span> ${num(c.nonzeros)} NNZ</span></div>${['cpu','cuda','highs'].map((e,i)=>`<div class="bar-row"><div class="bar-label"><span class="dot-${e}"></span>${e==='highs'?'HiGHS':e==='cpu'?'VANTAGE CPU':'VANTAGE GPU'}</div><div class="bar-track"><div class="bar-fill ${e}" style="width:${values[i]/max*100}%" title="${esc(engineName(e))}: ${time(c.engines[e]?.[state.timeMetric])}"></div></div><span class="bar-value">${time(c.engines[e]?.[state.timeMetric])}</span></div>`).join('')}<div class="chart-axis">${ticks.map(t=>`<span>${t.toFixed(t<.1?3:1)}s</span>`).join('')}</div></div><div class="chart-foot"><span>${c.engines.cuda?.status==='OPTIMAL'&&c.engines.cpu?.status==='OPTIMAL'?`<strong>${(c.engines.cpu.seconds/c.engines.cuda.seconds).toFixed(2)}×</strong> GPU speedup over our CPU`:'Limited runs are shown; their times are not solve speedups.'}</span><span>${c.engines.highs?.status==='OPTIMAL'?'HiGHS: reference solved':'Reference result unavailable'} <span class="note-arrow">↗</span></span></div></section>`;}
function health(){const solved=state.data.counts.cuda,total=state.data.total,ratio=total?solved/total:0;return `<section class="panel health-panel"><div class="panel-header"><div><span class="overline">NUMERICAL CONFIDENCE</span><h2>Evidence over promises.</h2><p>GPU outcomes across the selected suite.</p></div>${icon('shield')}</div><div class="health-top"><div class="health-ring"><svg viewBox="0 0 120 120" role="img" aria-label="${solved} of ${total} cases solved"><circle class="track" cx="60" cy="60" r="49"/><circle class="progress" cx="60" cy="60" r="49" stroke-dasharray="${ratio*307.88} 307.88"/></svg><div class="health-center"><b>${solved}<span class="muted">/${total}</span></b><small>VERIFIED</small></div></div><div class="health-key"><div><span class="small-dot"></span>Optimal<b>${String(solved).padStart(2,'0')}</b></div><div><span class="small-dot warn"></span>Limited / unresolved<b>${String(total-solved).padStart(2,'0')}</b></div><div><span class="small-dot" style="background:#adb4a1"></span>HiGHS optimal<b>${String(state.data.counts.highs).padStart(2,'0')}</b></div></div></div><div class="health-note"><b>A real foundation. Still a research prototype.</b>Accurate on solved cases. Harder LPs and mixed-integer search still need work.</div><div class="health-footer">${icon('check')} Residuals checked in original model units</div></section>`;}
function rowsTable(cases,compact=false){return `<div class="table-scroll"><table><thead><tr><th>MODEL / INSTANCE</th>${compact?'':'<th>CLASS</th>'}<th><button class="sort" data-sort="cpu">CPU TIME ↕</button></th><th><button class="sort" data-sort="cuda">GPU TIME ↕</button></th><th>HiGHS TIME</th><th>GPU STATUS</th>${compact?'':'<th>ACCURACY²</th>'}<th></th></tr></thead><tbody>${cases.length?cases.map(c=>`<tr data-case="${esc(c.id)}" tabindex="0" role="button" aria-label="Inspect ${esc(c.name)}"><td><span class="model-title"><span class="type-mark">${esc(c.type)}</span><span>${esc(c.name)}<small>${esc(c.category)} · ${num(c.columns)} variables</small></span></span></td>${compact?'':`<td><span class="pill gray">${esc(c.type)}</span></td>`}<td class="mono">${time(c.engines.cpu?.seconds)}</td><td class="mono">${time(c.engines.cuda?.seconds)}</td><td class="mono muted">${time(c.engines.highs?.seconds)}</td><td>${badge(c.engines.cuda?.status||'UNAVAILABLE')}</td>${compact?'':`<td class="mono">${sci(c.type==='MILP'?c.engines.cuda?.gap:c.engines.cuda?.kkt)}<small>${c.type==='MILP'?'MIP GAP':'KKT ERROR'}</small></td>`}<td>${icon('diagonal')}</td></tr>`).join(''):'<tr><td colspan="8" class="empty-table">No models match your search.</td></tr>'}</tbody></table></div>`;}
function overview(){const subset=['refinery','dispatch','supply_chain','refinery_large'].map(caseById).filter(Boolean);return heading('VANTAGE / GPU OPTIMIZATION ENGINE','Computation. At scale.','Your solver, its numerical health, and the evidence behind it.',`<a class="button light" href="/api/export.csv">${icon('download')} Export results</a><a class="button primary" href="#solve">${icon('plus')} New solve</a>`)+`<div class="run-banner">${icon('check')}<span>Benchmark snapshot loaded <span class="muted">— real measurements, including the runs that didn’t converge.</span></span><a href="#benchmarks"><span>Explore evidence</span>${icon('arrow')}</a></div>`+`<div class="command-board">`+coreView()+metricCards()+`<div class="overview-grid">${chart('refinery_large')}${health()}</div>${workflowView()}</div><section class="panel table-panel"><div class="panel-header"><div><h2>The latest from the benchmark lab</h2><p>A shared model, identical thread limits, independently checked results.</p></div><a class="link" href="#benchmarks">All ${state.data.total} cases ${icon('arrow')}</a></div>${rowsTable(subset,true)}<div class="table-end"><span>Median of 3 runs · Default tolerance 10⁻⁶</span><span>Times include setup and transfer</span></div></section><div class="insight-strip">${icon('info')}<span><b>How good is VANTAGE today?</b> An independent optimizer. GPU benefit must be established from paired optimal CPU and GPU runs. HiGHS remains substantially faster and more robust overall. ¹Objective agreement uses solved cases only; it does not certify the unresolved ones.</span></div>`;}
function benchmarkView(){return heading('MEASURE / COMPARE / VERIFY','Performance laboratory.','An honest view of speed, accuracy, and the distance still to go.',`<button class="button light" id="method-button">${icon('info')} Methodology</button><a class="button primary" href="/api/export.csv">${icon('download')} Download CSV</a>`)+metricCards()+benchmarkPlots()+evidencePlots()+`<div class="bench-top"><div id="benchmark-chart">${chart(state.compare,true)}</div><section class="panel verdict"><div class="eyebrow">THE CURRENT VERDICT</div><h2>Promising engineering.<br>Room to mature.</h2><p>${state.data.speedup>1?'The GPU is faster than our CPU on the large synthetic case.':'The measured CPU/GPU benefit depends on the case and configuration.'} Compare solve status and accuracy alongside time; HiGHS remains the external reference.</p><div class="verdict-list"><div>${icon('check')} ${state.data.counts.cuda}/${state.data.total} cases solved by VANTAGE GPU</div><div>${icon('check')} ${state.data.counts.highs}/${state.data.total} cases solved by HiGHS</div><div class="warning">${icon('warning')} Commercial solvers have not been benchmarked</div></div></section></div><div class="toolbar"><div class="tabs" aria-label="Filter benchmarks">${[['all','All cases'],['Netlib','Public LPs'],['Industrial','Industrial'],['Scalability','Scale test']].map(([v,l])=>`<button data-filter="${v}" class="${state.filter===v?'selected':''}">${l}</button>`).join('')}</div><label class="search">${icon('search')}<input id="case-search" placeholder="Find a model…" aria-label="Search models" value="${esc(state.query)}"></label></div><section class="panel table-panel"><div id="benchmark-table">${filteredTable()}</div><div class="table-end"><span id="table-count">${filteredCases().length} distinct cases · 3 measured runs each</span><span>Click a row for the full evidence</span></div></section><div class="insight-strip">${icon('info')}<span><b>Read accuracy with status.</b> ²For LP/QP, accuracy is the normalized KKT error. For MILP, it is the global MIP gap; continuous KKT does not prove integer optimality. Limited-run times are included for transparency, not treated as solved-instance speedups.</span></div>`;}
function filteredCases(){let cs=state.data.cases.filter(c=>(state.filter==='all'||c.category===state.filter)&&(c.name+' '+c.id).toLowerCase().includes(state.query.toLowerCase()));if(state.sort!=='default')cs.sort((a,b)=>(a.engines[state.sort]?.seconds??Infinity)-(b.engines[state.sort]?.seconds??Infinity));return cs;}
function filteredTable(){return rowsTable(filteredCases());}
function modelsView(){return heading('MODELS & APPLICATIONS','A library of real problems.','Public benchmark instances and clearly labeled synthetic industrial models.',`<a class="button primary" href="#solve">${icon('upload')} Import a model</a>`)+`<div class="model-grid">${state.models.map(m=>`<article class="panel model-card"><div class="model-card-head"><span class="model-icon">${icon(m.type==='QP'?'bolt':m.type==='MILP'?'layers':'file')}</span><span class="pill">${esc(m.type)}</span></div><h3>${esc(m.name)}</h3><p>${esc(m.description)}</p><div class="model-meta"><span><b>${num(m.columns)}</b> VARIABLES</span><span><b>${num(m.rows)}</b> ROWS</span></div><div class="model-card-foot"><span>${m.category==='Netlib'?'PUBLIC / NETLIB':m.category==='Uploaded'?'LOCAL UPLOAD':'SYNTHETIC DATA'}</span><button class="button small" data-run-model="${esc(m.id)}" ${m.available?'':'disabled'}>${m.available?'Open model':'Not generated'} ${icon('arrow')}</button></div></article>`).join('')}</div>`;}
function solveView(){return heading('EXECUTION / CONTROL','Solver cockpit.','Run the actual VANTAGE engine. Inspect the result before trusting the answer.',`<span class="pill green">${icon('chip')} FP64 ENGINE</span>`)+`<div class="solve-layout"><section class="panel form-panel"><h2>Configure a solve</h2><form id="solve-form"><div id="form-error" class="error-message" hidden></div><label class="field"><span class="field-label">Model</span><select name="model" id="model-select">${state.models.filter(m=>m.available).map(m=>`<option value="${esc(m.id)}" ${state.selectedModel===m.id?'selected':''}>${esc(m.name)} · ${esc(m.type)}</option>`).join('')}</select><small id="model-description">${esc(state.models.find(m=>m.id===state.selectedModel)?.description||'')}</small><button type="button" class="upload" id="upload-button">${icon('upload')} Import .mps, .lp or .json</button></label><input type="file" id="model-file" accept=".mps,.lp,.json" hidden><div class="field"><span class="field-label">Compute backend</span><div class="device-switch">${['cpu','cuda','auto'].map(v=>`<button type="button" data-device="${v}" class="${state.device===v?'selected':''}">${v==='cuda'?'GPU / CUDA':v.toUpperCase()}</button>`).join('')}</div><small>CPU is usually faster for small models.</small></div><label class="field"><span class="field-label">Target tolerance</span><select name="tol"><option value="0.0001">10⁻⁴ · Exploratory</option value="0.000001" selected>10⁻⁶ · Standard</option><option value="0.00000001">10⁻⁸ · Strict</option></select><small>Measured against original-space residuals.</small></label><div class="field-row"><label class="field"><span class="field-label">Time limit (s)</span><input type="number" name="time_limit" min="1" max="120" value="30" required></label><label class="field"><span class="field-label">CPU threads</span><input type="number" name="threads" min="1" max="32" value="4" required></label></div><label class="field"><span class="field-label">Iteration budget</span><input type="number" name="iterations" min="1" max="2000000" value="100000" required><small>Increase this if a run reaches its iteration limit. Applies to each LP relaxation in MILP.</small></label><div class="checks"><label class="check"><input type="checkbox" name="adaptive" checked>Adaptive step sizes</label><label class="check"><input type="checkbox" name="scaling" checked>Diagonal scaling</label><label class="check"><input type="checkbox" name="restart" checked>Adaptive restarts</label></div><div class="form-divider"></div><button class="button primary full" id="run-button">${icon('play')} Run optimization</button><p class="form-hint">One solve at a time. The time limit is checked between iteration chunks. Models stay on this machine.</p></form></section><div class="workspace-output"><div id="solve-output">${outputView()}</div><section class="history" id="run-history"></section></div></div>`;}
function outputView(){const j=state.job;if(!j)return coreView(true)+`<section class="panel output-empty"><div class="empty-symbol">${icon('terminal')}</div><h2>The next result starts here.</h2><p>Choose a model and run an optimization. Its objective, residuals and execution log will appear here.</p><div class="empty-tags"><span class="pill">LP</span><span class="pill">CONVEX DIAGONAL QP</span><span class="pill">MILP</span></div></section>`;const r=j.result;const running=j.state!=='finished';const a=r?.accuracy||{};return cockpit(j)+`<section class="panel ${r?.status==='OPTIMAL'?'optimal-result':''}"><div class="run-header"><div><h3>${esc(j.name)}</h3><small>${esc(j.options?.device.toUpperCase()||'')} · ${running?'Executing locally':time(r?.performance?.end_to_end_seconds)} · ${new Date(j.started_at*1000).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</small></div>${badge(r?.status||j.state)}</div>${r?`<div class="result-grid"><div class="result-item"><label>OBJECTIVE</label><strong>${objective(r.objective)}</strong></div><div class="result-item"><label>ITERATIONS</label><strong>${num(r.performance?.iterations)}</strong></div><div class="result-item"><label>PRIMAL RESIDUAL</label><strong>${sci(a.primal_residual)}</strong></div><div class="result-item"><label>${r.problem_type==='MILP'?'GLOBAL MIP GAP':'KKT ERROR'}</label><strong>${sci(r.problem_type==='MILP'?r.mip?.relative_gap:a.kkt_error)}</strong></div></div><div class="result-note">${r.message?esc(r.message):r.status==='OPTIMAL'?'The engine reports optimality within the configured numerical tolerances. Feasibility and diagnostics were checked in original model units.':'This run did not establish optimality. Its best candidate and available diagnostics are retained.'}</div>`:`<div class="result-grid"><div class="result-item"><label>ELAPSED</label><strong>${((Date.now()/1000)-j.started_at).toFixed(1)} s</strong></div><div class="result-item"><label>STATE</label><strong style="display:flex;gap:12px;align-items:center"><span class="loader"></span>Computing</strong></div></div>`}<div class="run-actions">${running?`<button class="button small" id="cancel-run">${icon('stop')} Stop run</button>`:`<a class="button small" href="/api/runs/${j.id}/download">${icon('download')} Download solution</a><button class="button small" id="copy-result">${icon('file')} Copy JSON</button>`}</div></section><section class="console"><div class="console-header"><span>ENGINE OUTPUT / ${esc(j.id.slice(0,8))}</span><span>${running?'LIVE':'COMPLETE'}</span></div><pre id="live-log" aria-label="Solver execution log">${esc(j.logs||(running?'Initializing the VANTAGE engine…':'No execution log was emitted.'))}</pre></section>`;}
function historyView(){const list=route()==='runs'?state.history:state.history.slice(0,6);return `<h3>Recent local runs</h3>${list.length?list.map(j=>`<button class="history-row" data-history="${esc(j.id)}"><span>${esc(j.name)}</span><small>${new Date(j.started_at*1000).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</small>${badge(j.result?.status||j.state)}</button>`).join(''):'<p class="subtitle">Completed runs will be saved here.</p>'}`;}
function render(){if(!state.data)return;let page=route();if(!Object.hasOwn(views,page))page='overview';$$('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===page);if(a.dataset.nav===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#breadcrumb-page').textContent=page.charAt(0).toUpperCase()+page.slice(1);window.VantageWave.dispose();$('#main').dataset.page=page;$('#main').innerHTML=views[page]();observeTiles();if(page==='overview')window.VantageWave.mount($('.command-board .core-stage'),()=>effectsEnabled&&!motionPreference.matches&&(!state.job||state.job.state==='finished'));closeNavigation();icons();if(page==='solve'||page==='import'){$('#run-history').innerHTML=historyView();$('#run-button').disabled=state.job&&state.job.state!=='finished';}document.title=`${$('#breadcrumb-page').textContent} — VANTAGE`;}
function closeDrawer(){ $('#drawer').hidden=true;$('#drawer-overlay').hidden=true;document.body.style.overflow='';state.returnFocus?.focus();}
function openDrawer(content){state.returnFocus=document.activeElement;$('#drawer').innerHTML=`<div class="drawer-head"><span class="eyebrow" style="margin:0">BENCHMARK EVIDENCE</span><button class="icon-button" id="close-drawer" aria-label="Close details">${icon('close')}</button></div>${content}`;$('#drawer').hidden=false;$('#drawer-overlay').hidden=false;document.body.style.overflow='hidden';$('#close-drawer').focus();}
function methodContent(){return `<div class="methodology"><h3>How these numbers were measured</h3><p>Three measured runs per model and backend. One CUDA warmup is retained separately. CPU and GPU use the same VANTAGE algorithm. HiGHS runs as a separate comparison process.</p><p>End-to-end timing includes parsing, initialization, transfer and verification. CPU thread limits match within each campaign. ${state.data.sources.map(s=>`${esc(s.suite)}: ${s.threads} threads, ${s.time_limit} s limit, ${num(s.iterations)} iterations, tolerance ${sci(s.tolerance)}`).join('; ')}.</p><p>Each instance is counted once. The completed Phase 2 campaign takes precedence when available. Every failure remains visible. This is a small selected suite, not a representative industrial solve-rate estimate.</p><p>Relative objective error = |VANTAGE − HiGHS| / max(1, |HiGHS|). The overview’s worst error uses optimal VANTAGE runs only. It does not establish optimality on unresolved cases.</p><p>QP support is diagonal convex only. A MILP’s continuous KKT error does not prove tree optimality; use its global MIP gap. Synthetic refinery periods are largely independent.</p><p>No Gurobi, CPLEX or SCIP comparisons have been measured. No inference about those solvers is made.</p></div>`;}
function showCase(id){const c=caseById(id);if(!c)return;openDrawer(`<h2>${esc(c.name)}</h2><div class="drawer-meta"><span class="pill">${c.type}</span><span class="pill">${esc(c.category)}</span><span class="pill">${num(c.columns)} VARIABLES</span></div>${['cpu','cuda','highs'].map(e=>{const r=c.engines[e];return r?`<section class="detail-engine"><div class="detail-engine-title">${engineName(e)} ${badge(r.status)}</div><dl class="detail-dl"><div><dt>Median end-to-end</dt><dd>${time(r.seconds)}</dd></div><div><dt>Objective</dt><dd>${objective(r.objective)}</dd></div><div><dt>Original-space primal residual</dt><dd>${sci(r.primal)}</dd></div><div><dt>${c.type==='MILP'?'Global MIP gap':'KKT error'}</dt><dd>${sci(c.type==='MILP'?r.gap:r.kkt)}</dd></div><div><dt>Relative objective error vs HiGHS</dt><dd>${sci(r.objective_error)}</dd></div><div><dt>Optimal repetitions</dt><dd>${r.solved} / ${r.runs}</dd></div></dl></section>`:'';}).join('')}<div class="drawer-links"><button class="button primary" data-run-model="${c.id}">${icon('play')} Run this model</button><a class="button" href="/reports/${c.suite}/index.html" target="_blank" rel="noopener">Raw report ${icon('diagonal')}</a></div>${methodContent()}`);}
async function refreshHistory(){try{state.history=await api('/api/runs');if($('#run-history'))$('#run-history').innerHTML=historyView();if(['verification','hardware','diagnostics'].includes(route()))render();}catch(e){toast(e.message);}}
async function poll(){if(!state.job)return;try{state.job=await api(`/api/runs/${state.job.id}`);if(['solve','import'].includes(route())){$('#solve-output').innerHTML=outputView();$('#run-button').disabled=state.job.state!=='finished';const log=$('#live-log');if(log)log.scrollTop=log.scrollHeight;}if(state.job.state==='finished'){await refreshHistory();return;}state.timer=setTimeout(poll,700);}catch(e){toast(e.message);state.timer=setTimeout(poll,1800);}}
async function upload(file){if(!file)return;if(file.size>5_000_000){toast('Choose a text model smaller than 5 MB. Larger generated cases are available in the library.');return;}try{toast('Validating your model…');const model=await api('/api/upload',{name:file.name,content:await file.text()});state.models.push(model);state.selectedModel=model.id;render();toast('Model validated and added to your workspace.');}catch(e){toast(e.message);}}
document.addEventListener('click',async e=>{
 const target=e.target.closest('button,a,[data-case]');if(!target)return;
 if(target.id==='menu-button'){const open=$('#sidebar').classList.toggle('open');$('#menu-button').setAttribute('aria-expanded',String(open));if(!open)setPlatformOpen(false);return;}
 if(target.id==='close-drawer'){closeDrawer();return;}
 if(target.id==='method-button'){openDrawer(`<h2>A fairer comparison.</h2><p class="subtitle">The scope, settings and limitations behind every number.</p>${methodContent()}<div class="drawer-links"><a class="button" href="/api/export.csv">${icon('download')} Export all cases</a></div>`);return;}
 if(target.dataset.case){showCase(target.dataset.case);return;}
 if(target.dataset.filter){state.filter=target.dataset.filter;render();return;}
 if(target.dataset.sort){state.sort=target.dataset.sort;const table=$('#benchmark-table');if(table)table.innerHTML=filteredTable();return;}
 if(target.dataset.runModel){state.selectedModel=target.dataset.runModel;closeDrawer();if(['solve','import'].includes(route()))render();else location.hash='solve';return;}
 if(target.dataset.device){state.device=target.dataset.device;$$('[data-device]').forEach(b=>b.classList.toggle('selected',b.dataset.device===state.device));return;}
 if(target.id==='upload-button'){$('#model-file').click();return;}
 if(target.dataset.history){if(state.job&&state.job.state!=='finished'&&state.job.id!==target.dataset.history){toast('Wait for the active solve to finish, or stop it first.');return;}clearTimeout(state.timer);state.job=await api(`/api/runs/${target.dataset.history}`);if(!$('#solve-output')){location.hash='solve';return;}$('#solve-output').innerHTML=outputView();if(state.job.state!=='finished')poll();return;}
 if(target.id==='cancel-run'){target.disabled=true;try{await api(`/api/runs/${state.job.id}/cancel`,{});toast('Stop requested. Waiting for the current iteration chunk.');}catch(err){toast(err.message);}return;}
 if(target.id==='copy-result'){try{await navigator.clipboard.writeText(JSON.stringify(state.job.result,null,2));toast('Result JSON copied.');}catch{toast('Clipboard unavailable. Use Download solution.');}}
});
document.addEventListener('input',e=>{if(e.target.id==='case-search'){state.query=e.target.value;$('#benchmark-table').innerHTML=filteredTable();$('#table-count').textContent=`${filteredCases().length} distinct cases · 3 measured runs each`;}});
document.addEventListener('change',e=>{if(e.target.id==='compare-case'){state.compare=e.target.value;$('#benchmark-chart').innerHTML=chart(state.compare,true);}if(e.target.id==='time-metric'){state.timeMetric=e.target.value;$('#benchmark-chart').innerHTML=chart(state.compare,true);}if(e.target.id==='model-select'){state.selectedModel=e.target.value;$('#model-description').textContent=state.models.find(m=>m.id===state.selectedModel)?.description||'';}if(e.target.id==='model-file')upload(e.target.files[0]);});
document.addEventListener('submit',async e=>{if(e.target.id!=='solve-form')return;e.preventDefault();const f=new FormData(e.target);const b=$('#run-button');b.disabled=true;$('#form-error').hidden=true;try{state.job=await api('/api/runs',{model:f.get('model'),device:state.device,tol:Number(f.get('tol')),time_limit:Number(f.get('time_limit')),threads:Number(f.get('threads')),iterations:Number(f.get('iterations')),adaptive:f.has('adaptive'),scaling:f.has('scaling'),restart:f.has('restart')});clearTimeout(state.timer);$('#solve-output').innerHTML=outputView();poll();}catch(err){$('#form-error').textContent=err.message;$('#form-error').hidden=false;b.disabled=false;}});
$('#drawer-overlay').addEventListener('click',closeDrawer);
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('#drawer').hidden)closeDrawer();}const row=e.target.closest('[data-case]');if(row&&(e.key==='Enter'||e.key===' ')){e.preventDefault();showCase(row.dataset.case);}if(e.key==='Tab'&&!$('#drawer').hidden){const focusable=$$('a,button,input,select,[tabindex="0"]',$('#drawer'));const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('hashchange',()=>{closeDrawer();render();window.scrollTo(0,0);});
(async()=>{icons();try{const d=await api('/api/bootstrap');state.binaryAvailable=d.binary_available;state.token=d.token;state.data=d.benchmarks;state.models=d.models;$('#nav-count').textContent=d.benchmarks.total;$('#engine-label').textContent=d.binary_available?'VANTAGE engine available':'Build the engine to solve';render();await refreshHistory();const active=state.history.find(j=>j.state!=='finished');if(active){state.job=active;poll();}}catch(e){$('#main').innerHTML=`<div class="loading"><div><h2>Workspace unavailable</h2><p>${esc(e.message)}</p><p>Start the local server with <code>./scripts/run_dashboard.sh</code>.</p><button class="button" onclick="location.reload()">Try again</button></div></div>`;}})();

// Presentation helpers consume existing API values; schematics never represent telemetry.
function instrument(label,value){return `<div class="instrument"><span>${esc(label)}</span><strong>${value}</strong></div>`;}
function coreView(compact=false){const m=state.models.find(m=>m.id===(compact?state.selectedModel:'refinery_large')&&m.columns!=null)||state.models.find(m=>m.columns!=null)||state.models[0];return `<section class="compute-hero ${compact?'compact':''}"><div class="core-copy"><div class="eyebrow">${compact?'READY FOR EXECUTION':'NUMERICAL COMPUTING / 01'}</div><h2>${compact?'The compute pipeline.':'Sparse structure.<br>Massive possibility.'}</h2><p>${compact?'Configure the engine to begin a measured run.':'An independent optimization engine.<br>Original-space verification. Reproducible evidence.'}</p><div class="core-caption">${esc(m?.name||'No model loaded')} · MODEL DIMENSIONS</div><div class="core-metrics">${instrument('VARIABLES',num(m?.columns))}${instrument('CONSTRAINTS',num(m?.rows))}${instrument('NONZEROS',num(m?.nonzeros))}</div></div><div class="core-stage" aria-label="Decorative computation schematic"><div class="orbital orbital-back"></div><div class="orbital"></div><div class="core-chip"><span>V A N T A G E</span><strong>A · x</strong><div class="core-rule"></div><strong>Aᵀ · y</strong><small>FP64 / COMPUTE CORE</small></div><span class="stage-label">COMPUTATION SCHEMATIC · NOT TELEMETRY</span></div></section>`;}
function convergence(j){if(j.result?.problem_type==='MILP')return `<p class="telemetry-note">LP relaxation logs are retained below; they do not represent global MIP convergence.</p>`;const samples=[...(j.logs||'').matchAll(/iter=(\d+) objective=\S+ primal=(\S+) dual=(\S+) gap=(\S+)/g)].map(m=>({x:+m[1],y:Math.max(+m[2],+m[3],Math.abs(+m[4]))})).filter(p=>Number.isFinite(p.y)&&p.y>=0);if(!samples.length)return `<p class="telemetry-note">Convergence trace awaits solver log samples. Final KKT is reported separately.</p>`;const target=j.options?.tol||1e-6;const ys=samples.map(p=>Math.log10(Math.max(p.y,1e-16)));const hi=Math.ceil(Math.max(...ys,Math.log10(target)))+1,lo=Math.floor(Math.min(...ys,Math.log10(target)))-1;const xmax=Math.max(...samples.map(p=>p.x),1);const px=x=>55+x/xmax*650,py=y=>25+(hi-Math.log10(Math.max(y,1e-16)))/(hi-lo)*150;const last=samples.at(-1);return `<section class="panel convergence"><div class="panel-header"><div><span class="overline">CONVERGENCE / LOG SCALE</span><h2>Original-space residual envelope</h2><p>max(primal, dual, |gap|) · logged samples only</p></div><span class="pill">ITER ${num(last.x)}</span></div><svg viewBox="0 0 760 220" role="img" aria-label="Residual envelope by iteration"><g class="plot-grid">${[hi,(hi+lo)/2,lo].map(v=>`<path d="M55 ${py(10**v)}H705"/><text x="4" y="${py(10**v)+4}">10^${v.toFixed(0)}</text>`).join('')}</g><path class="target-line" d="M55 ${py(target)}H705"/><text class="plot-label" x="560" y="${py(target)-7}">TARGET ${sci(target)}</text><polyline class="trace" points="${samples.map(p=>`${px(p.x)},${py(p.y)}`).join(' ')}"/><circle class="latest-point" cx="${px(last.x)}" cy="${py(last.y)}" r="4"/><text class="plot-label" x="55" y="207">0</text><text class="plot-label" x="630" y="207">${num(xmax)} ITER</text></svg></section>`;}
function cockpit(j){const r=j.result, active=j.state==='running',good=['OPTIMAL','VERIFIED_OPTIMAL'].includes(r?.status);return `<section class="cockpit ${active?'is-running':''} ${good?'is-optimal':''}"><div class="cockpit-top"><span>${esc(r?.problem_type||state.models.find(m=>m.id===j.model)?.type||'OPTIMIZATION')} / ${esc(r?.hardware?.precision||'FP64')}</span><span>${good?'✓ OPTIMAL':esc(r?.status||j.state).toUpperCase()}</span></div><div class="pipeline"><span class="matrix-glyph" aria-hidden="true">⠿ ⠇ ⠿<br>⠙ ⠿ ⠋<br>⠿ ⠉ ⠿</span><span class="flow-wire"></span><span>A · x</span><span class="flow-wire"></span><div class="pipeline-core"><small>${esc(r?.hardware?.backend?.toUpperCase()||'ENGINE')}</small>${esc(r?.hardware?.device||'AWAITING DEVICE')}</div><span class="flow-wire"></span><span>Aᵀ · y</span></div><div class="cockpit-metrics">${instrument('DEVICE',esc(r?.hardware?.device||'Not yet reported'))}${instrument('RESTARTS',num(r?.performance?.restarts))}${instrument('DUAL RESIDUAL',sci(r?.accuracy?.dual_residual))}${instrument('GPU MEMORY','Unavailable')}</div><p class="telemetry-note">Schematic flow ${active?'animates while the process is running':'is idle'}; it does not measure GPU activity.</p></section>${convergence(j)}${applicationView(r)}`;}
function applicationView(r){if(!r)return '';if(r.problem_type==='MILP')return `<section class="panel application-panel"><div class="eyebrow">BRANCH & BOUND</div><h2>Integer search</h2><div class="tree-schematic" aria-label="Illustrative branch tree, not actual search history"><span>ROOT</span><div>╱ ────── ╲</div><div><span class="cyan">OPEN</span>　 <span class="lime">INCUMBENT</span></div><div>╱　╲　　 ╱　╲</div><div>PRUNED　　 <span class="error-text">INFEASIBLE</span></div></div><p class="telemetry-note">Illustrative node-state key. Search topology is not exposed by the engine.</p><div class="cockpit-metrics">${instrument('NODES PROCESSED',num(r.mip?.nodes))}${instrument('NODES REMAINING',num(r.mip?.nodes_remaining))}${instrument('BEST BOUND',objective(r.mip?.best_bound))}${instrument('GLOBAL MIP GAP',sci(r.mip?.relative_gap))}</div></section>`;const names=r.model?.variable_names||[];const values=r.primal||[];if(r.problem_type==='QP'){const max=Math.max(...values.map(Math.abs),1);return `<section class="panel application-panel"><div class="eyebrow">POWER DISPATCH / SOLUTION VECTOR</div><h2>Generation → load</h2><p class="telemetry-note">Actual primal values in model units; unavailable counters are omitted.</p><div class="dispatch-flows">${values.slice(0,12).map((v,i)=>`<div><span>${esc(names[i]||`Variable ${i+1}`)}</span><div class="dispatch-track"><b style="width:${Math.abs(v)/max*100}%"></b></div><strong>${objective(v)}</strong></div>`).join('')}</div>${values.length>12?'<p class="telemetry-note">First 12 variables. Download the full solution for all outputs.</p>':''}</section>`;}if(r.model?.name?.includes('refinery'))return `<section class="panel application-panel"><div class="eyebrow">REFINERY / PROCESS SCHEMATIC</div><h2>Feedstock to products</h2><div class="refinery-schematic"><div class="tanks"><span>CRUDE A</span><span>CRUDE B</span></div><div class="plant-pipes">╲────────┬────────╱</div><div class="distillation">CDU<small>DISTILLATION</small></div><div class="plant-pipes">╱────────┴────────╲</div><div class="products"><span>NAPHTHA</span><span>DIESEL</span><span>RESIDUE</span></div></div><p class="telemetry-note">Conceptual process layout, not model topology or measured flow.</p><div class="cockpit-metrics">${values.slice(0,4).map((v,i)=>instrument(names[i]||`FLOW ${i+1}`,objective(v))).join('')}</div></section>`;return '';}
function benchmarkPlots(){const series=['cuda','cpu','highs'].map(e=>({e,points:state.data.cases.filter(c=>c.engines[e]?.status==='OPTIMAL'&&Number.isFinite(c.engines[e].seconds)).map(c=>c.engines[e].seconds).sort((a,b)=>a-b)}));const max=Math.max(...series.flatMap(s=>s.points),.001),count=Math.max(...series.map(s=>s.points.length),1);return `<section class="panel research-plot"><div class="panel-header"><div><span class="overline">CACTUS / SOLVED INSTANCES</span><h2>Time to a verified result</h2><p>Sorted median end-to-end time · optimal cases only · linear axes</p></div><div class="plot-legend"><span class="cyan">GPU</span><span>CPU</span><span>HiGHS</span></div></div><svg viewBox="0 0 900 190" role="img" aria-label="Cactus plot: solved instance count versus seconds">${[0,.5,1].map(t=>`<g class="plot-grid"><path d="M65 ${145-t*120}H860"/><text x="8" y="${149-t*120}">${(max*t).toFixed(2)}s</text></g>`).join('')}${series.map((s,i)=>`<polyline fill="none" stroke="${['#00E5FF','#F2F7FA','#788898'][i]}" stroke-width="2" ${i?'stroke-dasharray="5 4"':''} points="${s.points.map((v,n)=>`${65+(n+1)/count*795},${145-v/max*120}`).join(' ')}"/>`).join('')}<text class="plot-label" x="65" y="177">0</text><text class="plot-label" x="715" y="177">${count} SOLVED INSTANCES</text></svg></section>`;}
function latestResult(){return state.job?.result?state.job:state.history.find(j=>j.result);}
function verificationView(){const j=latestResult(),r=j?.result;return heading('ANALYSIS / ORIGINAL-SPACE CHECKS','Numerical verification.','Diagnostics reported by the solver’s original-space verification pass.')+(!r?`<section class="panel application-panel"><h2>No result to inspect</h2><p class="subtitle">Run a model or select a saved run to inspect its diagnostics.</p><a class="button" href="#solve">Open solver</a></section>`:`<section class="panel application-panel"><div class="run-header"><h2>${esc(j.name)}</h2>${badge(r.status)}</div><dl class="verification-list">${[['Objective',objective(r.objective)],['Primal residual',sci(r.accuracy?.primal_residual)],['Dual residual',sci(r.accuracy?.dual_residual)],['KKT error',sci(r.accuracy?.kkt_error)],[r.problem_type==='MILP'?'Global MIP gap':'Relative gap',sci(r.problem_type==='MILP'?r.mip?.relative_gap:r.accuracy?.relative_gap)],['Integrality',sci(r.accuracy?.integrality)],['Finite values',r.accuracy?.finite===true?'YES':r.accuracy?.finite===false?'NO':'Unavailable'],['Configured tolerance',sci(j.options?.tol)]].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl><p class="telemetry-note">A separate independent recomputation and per-constraint pass counts are not exposed. MILP optimality requires the global MIP gap, not continuous KKT alone.</p></section>`);}
function systemView(){const j=latestResult(),r=j?.result;return heading('SYSTEM / LOCAL ENGINE','Compute environment.','Hardware identity from the selected or latest result.')+`<section class="panel application-panel"><div class="cockpit-metrics">${instrument('ENGINE BINARY',state.binaryAvailable?'AVAILABLE':'NOT BUILT')}${instrument('DEVICE',esc(r?.hardware?.device||'Not yet reported'))}${instrument('BACKEND',esc(r?.hardware?.backend||'Not yet reported'))}${instrument('PRECISION',esc(r?.hardware?.precision||'Not yet reported'))}</div><p class="telemetry-note">${j?`Source: ${esc(j.name)} · ${esc(j.id.slice(0,8))}. `:''}GPU utilization, VRAM and temperature telemetry are unavailable.</p></section>`+coreView(true);}
const views={overview,benchmarks:benchmarkView,solve:solveView,models:modelsView,import:solveView,runs:()=>heading('CORE / EXECUTION ARCHIVE','Run history.','Inspect saved local results and download the original solution.')+`<section id="run-history" class="history">${historyView()}</section>`,verification:verificationView,hardware:systemView,diagnostics:()=>heading('SYSTEM / DIAGNOSTICS','Engine console.','Unmodified output from the selected or latest run.')+`<section class="console"><div class="console-header">SOLVER OUTPUT</div><pre>${esc(state.job?.logs||'Open a saved run or execute a model to load its log.')}</pre></section>`,docs:()=>heading('REFERENCE / WORKSPACE','Operating the engine.','A local interface to the independent VANTAGE optimizer.')+`<section class="panel application-panel methodology"><h3>01 / Configure</h3><p>Choose a library model or import a text MPS, LP or JSON file. Select CPU, CUDA or auto, then set the tolerance, time limit and iteration budget.</p><h3>02 / Execute</h3><p>One solve runs at a time. The console displays actual engine output. Stop requests take effect between iteration chunks. CUDA requires a CUDA-enabled engine build.</p><h3>03 / Inspect</h3><p>Review solve status, original-space residuals and objective. For MILP, inspect the global MIP gap. Download solution JSON to retain the complete primal and dual vectors.</p><h3>04 / Compare</h3>${methodContent()}</section>`};
let effectsEnabled=true;try{effectsEnabled=localStorage.getItem('vantage-effects')!=='off';}catch{}
function applyEffects(){document.body.classList.toggle('effects-off',!effectsEnabled);const b=$('#effects-toggle');b.textContent=`Effects ${effectsEnabled?'on':'off'}`;b.setAttribute('aria-pressed',String(effectsEnabled));}
applyEffects();$('#effects-toggle').addEventListener('click',()=>{effectsEnabled=!effectsEnabled;applyEffects();try{localStorage.setItem('vantage-effects',effectsEnabled?'on':'off');}catch{}});
function evidencePlots(){const cs=state.data.cases;const scatter=(title,xlabel,ylabel,points,agreement=false)=>{if(!points.length)return `<section class="panel application-panel"><h2>${title}</h2><p class="telemetry-note">No paired measurements available.</p></section>`;const xmax=Math.max(...points.map(p=>p.x),1e-12),ymax=Math.max(...points.map(p=>p.y),1e-12);return `<section class="panel"><div class="panel-header"><div><h2>${title}</h2><p>${xlabel} / ${ylabel} · linear axes</p></div></div><svg class="evidence-svg" viewBox="0 0 450 210" role="img" aria-label="${title}"><g class="plot-grid">${[0,.5,1].map(t=>`<path d="M75 ${160-t*130}H425"/><text x="3" y="${164-t*130}">${(ymax*t).toExponential(1)}</text>`).join('')}</g>${points.map(p=>`<circle cx="${75+p.x/xmax*350}" cy="${160-p.y/ymax*130}" r="3" fill="${agreement?'#B6FF00':'#00E5FF'}"><title>${esc(p.name)}: ${p.x}, ${p.y}</title></circle>`).join('')}<text class="plot-label" x="75" y="185">0</text><text class="plot-label" x="305" y="185">${xmax.toExponential(1)}</text><text class="plot-label" x="170" y="204">${xlabel}</text></svg></section>`;};return `<div class="evidence-grid">${scatter('Solve time vs sparsity','NONZEROS','GPU SECONDS',cs.filter(c=>c.nonzeros>0&&c.engines.cuda?.status==='OPTIMAL'&&Number.isFinite(c.engines.cuda.seconds)).map(c=>({x:c.nonzeros,y:c.engines.cuda.seconds,name:c.name})))}${scatter('GPU / CPU speedup','NONZEROS','CPU SECONDS / GPU SECONDS',cs.filter(c=>c.nonzeros>0&&c.engines.cuda?.status==='OPTIMAL'&&c.engines.cpu?.status==='OPTIMAL'&&c.engines.cuda.seconds>0&&Number.isFinite(c.engines.cpu.seconds)).map(c=>({x:c.nonzeros,y:c.engines.cpu.seconds/c.engines.cuda.seconds,name:c.name})))}${scatter('Objective agreement','CASE INDEX','RELATIVE ERROR VS HiGHS',cs.flatMap((c,i)=>c.engines.cuda?.status==='OPTIMAL'&&Number.isFinite(c.engines.cuda.objective_error)?[{x:i+1,y:c.engines.cuda.objective_error,name:c.name}]:[]),true)}${profilePlot()}</div><p class="telemetry-note">Memory vs NNZ is unavailable: benchmark artifacts do not expose memory measurements.</p>`;}
function profilePlot(){const engines=['cuda','cpu','highs'],cs=state.data.cases;const ratios=engines.map(e=>cs.map(c=>{const best=Math.min(...engines.map(k=>c.engines[k]?.status==='OPTIMAL'&&c.engines[k].seconds>0?c.engines[k].seconds:Infinity));return c.engines[e]?.status==='OPTIMAL'&&c.engines[e].seconds>0&&Number.isFinite(best)?c.engines[e].seconds/best:Infinity;}));const finite=ratios.flat().filter(Number.isFinite),max=Math.max(...finite,2);return `<section class="panel"><div class="panel-header"><div><h2>Performance profile</h2><p>Fraction of all ${cs.length} cases solved within τ × fastest · log₂ τ</p></div></div><svg class="evidence-svg" viewBox="0 0 450 210" role="img" aria-label="Performance profile including unsolved cases in denominator"><g class="plot-grid">${[0,.5,1].map(t=>`<path d="M55 ${160-t*130}H425"/><text x="8" y="${164-t*130}">${t*100}%</text>`).join('')}</g>${ratios.map((rs,i)=>{let path='M55 160';for(const tau of [...new Set([1,...rs.filter(Number.isFinite),max])].sort((a,b)=>a-b)){const x=55+Math.log2(tau)/Math.log2(max)*370;path+=`H${x}V${160-rs.filter(v=>v<=tau).length/Math.max(cs.length,1)*130}`;}return `<path d="${path}" fill="none" stroke="${['#00E5FF','#F2F7FA','#788898'][i]}" stroke-width="2" ${i?'stroke-dasharray="4 3"':''}/>`;}).join('')}<text class="plot-label" x="55" y="185">1×</text><text class="plot-label" x="350" y="185">${max.toFixed(1)}×</text></svg><div class="plot-legend profile-legend"><span class="cyan">GPU</span><span>CPU</span><span>HiGHS</span></div></section>`;}
document.addEventListener('visibilitychange',()=>document.body.classList.toggle('page-hidden',document.hidden));

// Layout and entrance treatment adapted from Zepa UI — any-grid.
// https://zepa.design/components/any-grid — Free to use; not for resale as a component.
function workflowView() {
  const available=state.models.filter(model=>model.available).length;
  return `<section class="panel workflow-tile">
    <div class="workflow-heading"><span class="overline">THE WORKSPACE</span><h2>One model.<br>A complete evidence trail.</h2><p>Configure, execute, inspect.</p></div>
    <div class="workflow-links">
      <a href="#models"><span class="workflow-icon">${icon('layers')}</span><span>Model library<small>${num(available)} available locally</small></span>${icon('arrow')}</a>
      <a href="#solve"><span class="workflow-icon">${icon('terminal')}</span><span>Solver cockpit<small>LP · convex diagonal QP · MILP</small></span>${icon('arrow')}</a>
      <a href="#verification"><span class="workflow-icon">${icon('shield')}</span><span>Inspect the result<small>Original-space numerical checks</small></span>${icon('arrow')}</a>
    </div>
    <div class="workflow-seal"><img src="/favicon.svg" width="70" height="70" alt=""><span>INDEPENDENT ENGINE</span><strong>Precision is the point.</strong></div>
  </section>`;
}
let tileObserver;
function observeTiles() {
  tileObserver?.disconnect();
  if (!('IntersectionObserver' in window)) return;
  tileObserver=new IntersectionObserver(entries=>{
    for(const entry of entries) {
      if(!entry.isIntersecting) continue;
      entry.target.classList.add('tile-entered');
      tileObserver.unobserve(entry.target);
    }
  },{threshold:0.08});
  $$('.command-board > .compute-hero, .stat, .panel, .cockpit', $('#main')).forEach((tile,index)=>{
    tile.classList.add('bento-tile');
    tile.style.setProperty('--tile-delay',`${Math.min(index%4*40,120)}ms`);
    tileObserver.observe(tile);
  });
}

// Zepa UI cohort-navbar adaptation: https://zepa.design/components/cohort-navbar
// Free to use in projects; not for resale as a component.
let platformHoverOpened=false;
function setPlatformOpen(open){
  if(!open)platformHoverOpened=false;
  $('#platform-toggle').setAttribute('aria-expanded',String(open));
  $('#platform-panel').hidden=!open;
}
function closeNavigation(){
  $('#sidebar').classList.remove('open');
  $('#menu-button').setAttribute('aria-expanded','false');
  setPlatformOpen(false);
}
$('#platform-toggle').addEventListener('click',()=>{const open=platformHoverOpened||$('#platform-panel').hidden;platformHoverOpened=false;setPlatformOpen(open);});
$('.platform-menu').addEventListener('pointerenter',e=>{
  if(e.pointerType==='mouse'&&innerWidth>1050&&$('#platform-panel').hidden){setPlatformOpen(true);platformHoverOpened=true;}
});
$('.platform-menu').addEventListener('pointerleave',()=>{
  if(!$('.platform-menu').contains(document.activeElement))setPlatformOpen(false);
});
$('.platform-menu').addEventListener('focusout',e=>{
  if(!$('.platform-menu').contains(e.relatedTarget))setPlatformOpen(false);
});
$$('[data-preview]').forEach(link=>{
  const preview=()=>{
    $('#preview-title').textContent=link.dataset.preview;
    $('#preview-description').textContent=link.dataset.description;
  };
  link.addEventListener('pointerenter',preview);link.addEventListener('focus',preview);
});
document.addEventListener('click',e=>{
  if(!$('.cohort-header').contains(e.target))closeNavigation();
  if(e.target.closest('.cohort-header a')){closeNavigation();window.scrollTo(0,0);}
});
document.addEventListener('keydown',e=>{
  if(e.key==='Escape'&&$('.cohort-header').contains(e.target)){
    if(!$('#platform-panel').hidden){setPlatformOpen(false);$('#platform-toggle').focus();}
    else{closeNavigation();$('#menu-button').focus();}
  }
  if(e.key==='ArrowDown'&&e.target.id==='platform-toggle'){
    e.preventDefault();setPlatformOpen(true);$('.mega-links a').focus();
  }
});

// Finite label-only scrambling. Stable original text keeps layout and accessibility intact.
const motionPreference=window.matchMedia('(prefers-reduced-motion: reduce)');
const labelAnimations=new Map();
function settleLabel(label){
  clearInterval(labelAnimations.get(label));
  labelAnimations.delete(label);
  label.querySelector('.scramble-visual').textContent=label.dataset.text;
}
function scrambleLabel(label){
  settleLabel(label);
  if(motionPreference.matches||!effectsEnabled||document.hidden)return;
  const original=label.dataset.text,started=performance.now(),glyphs='ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  const paint=()=>{
    const progress=Math.min((performance.now()-started)/320,1);
    label.querySelector('.scramble-visual').textContent=[...original].map((letter,index)=>{
      if(!/[a-z]/i.test(letter)||index<Math.floor(progress*original.length))return letter;
      const glyph=glyphs[Math.floor(Math.random()*glyphs.length)];
      return letter===letter.toLowerCase()?glyph.toLowerCase():glyph;
    }).join('');
    if(progress===1)settleLabel(label);
  };
  labelAnimations.set(label,setInterval(paint,35));paint();
}
$$('.cohort-nav>a, #platform-toggle, .mega-links>a').forEach(control=>{
  const parent=control.matches('.mega-links>a')?control.querySelector(':scope > span'):control;
  const textNode=[...parent.childNodes].find(node=>node.nodeType===Node.TEXT_NODE&&node.textContent.trim());
  if(!textNode)return;
  const label=document.createElement('span');label.className='scramble-label';label.dataset.text=textNode.textContent.trim();
  const original=document.createElement('span');original.className='scramble-original';original.textContent=label.dataset.text;
  const visual=document.createElement('span');visual.className='scramble-visual';visual.setAttribute('aria-hidden','true');visual.textContent=label.dataset.text;
  label.append(original,visual);textNode.replaceWith(label);
  control.addEventListener('pointerenter',()=>scrambleLabel(label));
  control.addEventListener('focus',()=>scrambleLabel(label));
  control.addEventListener('click',()=>scrambleLabel(label));
  control.addEventListener('pointerleave',()=>settleLabel(label));
  control.addEventListener('blur',()=>settleLabel(label));
});
function settleAllLabels(){for(const label of labelAnimations.keys())settleLabel(label);}
motionPreference.addEventListener('change',settleAllLabels);
$('#effects-toggle').addEventListener('click',settleAllLabels);
document.addEventListener('visibilitychange',()=>{if(document.hidden)settleAllLabels();});
